    "ar-stationary" -> FitConfig(autocorrelation = ArOptions(ArStructure.Ar(2), initialization = Some(ArInitialization.Stationary))),
    "ar-correction" -> FitConfig(autocorrelation = ArOptions(ArStructure.Ar(2), biasCorrection = ArBiasCorrection.olsTailAnchored(11).toOption.get)),
