  test("response-preparation and profile configuration identities have literal goldens"):
    cases.foreach: (name, config) =>
      assertEquals(
        ResponsePreparationIdentity.provenance(ResponsePreparationPlan.fromConfig(config).provenance),
        responsePreparationGoldens(name)
      )
      assertEquals(ProfileFitIdentity.config(config), profileFitConfigGoldens(name))
